BS.mountMedia=el=>{if(!el||mbox.parentNode===el)return;const yt=P.kind==='yt'&&P.has;el.appendChild(mbox);if(yt)P._remount=true};
const P=BS.P={has:false,playing:false,base:0,perf:0,rate:1,dur:0,pend:false,src:null,ended:false,kind:'file',ytOff:0,yt:YTD,_hold:false,_lmt:null,
 isYt(){return this.has&&this.kind==='yt'},
 hasVideo(){return this.has&&(this.kind==='yt'||vid.videoWidth>0)},
 mt(){return this.kind==='yt'?YTD.t()-this.ytOff:vid.currentTime},
 mseek(t){if(this.kind==='yt')YTD.seek(t+this.ytOff);else try{vid.currentTime=t}catch(e){}},
 mplay(){if(this.kind==='yt'){YTD.rate(this.rate);YTD.play();return Promise.resolve()}vid.playbackRate=this.rate;return vid.play()},
 mpause(){if(this.kind==='yt')YTD.pause();else vid.pause()},
 setVol(v){try{vid.volume=v}catch(e){}if(this.kind==='yt')YTD.vol(v)},
 async load(src){if(src&&src===this.src&&this.has&&!this._remount)return false;this.unload();if(!src)return false;this.src=src;
  const m=/^yt:([\w-]{11})@(-?[\d.]+)$/.exec(src);
  if(m){this.kind='yt';this.ytOff=(+m[2]||0)/1000;this.has=true;vid.style.display='none';const ok=await YTD.load(m[1]);
   if(!ok){BS.toast(YTD.err?BS.ytErrMsg(YTD.err):'유튜브에 연결하지 못했습니다. 인터넷 연결을 확인해 주십시오.');YTD.kill();this.has=false;this.kind='file';vid.style.display='';this.src=null;return false}
   this.dur=Math.max(0,YTD.dur()-this.ytOff);YTD.vol(BS.musicLevel());return true}
  this.kind='file';vid.style.display='';vid.src=src;this.has=true;
  await new Promise(res=>{let ok=false;const done=()=>{if(ok)return;ok=true;vid.removeEventListener('loadedmetadata',done);vid.removeEventListener('error',done);res()};vid.addEventListener('loadedmetadata',done);vid.addEventListener('error',done);setTimeout(done,10000)});
  this.dur=isFinite(vid.duration)?vid.duration:0;if(vid.error){BS.toast('영상/음악 파일을 재생할 수 없습니다 (mp4, webm, mp3 권장)');this.has=false}return true},
 async warm(){if(this.isYt())await YTD.warm(BS.adMode);if(this.isYt()&&!this.dur)this.dur=Math.max(0,YTD.dur()-this.ytOff)},
 setYtOff(ms){ms=Math.round(+ms||0);const t=this.time();this.ytOff=ms/1000;if(this.src&&/^yt:/.test(this.src))this.src=this.src.replace(/@.*$/,'@'+ms);if(this.isYt()){const d=YTD.dur();if(d)this.dur=Math.max(0,d-this.ytOff);if(t>=0)this.mseek(t)}},
 unload(){this._remount=false;this.pause();vid.removeAttribute('src');try{vid.load()}catch(e){}YTD.kill();vid.style.display='';this.has=false;this.dur=0;this.src=null;this.kind='file'},
 time(){if(!this.playing)return this.base;const now=performance.now();let t=this.base+(now-this.perf)/1000*this.rate;
  if(this.has){if(this.pend){if(t>=0){this.pend=false;this.mseek(0);this.mplay().catch(()=>{});this.base=0;this.perf=now;t=0}}
   else if(this.kind==='yt'){const st=YTD.ready?YTD.state:-1;if(!this.dur){const d=YTD.dur();if(d)this.dur=Math.max(0,d-this.ytOff)}
    if(st===0){this.ended=true}
    else if(st===1){if(this._hold){this._hold=false;this.perf=now;t=this.base}const mt=this.mt();
     // the embed reports its time in coarse steps: only trust a fresh value, nudge small drift, snap large drift
     if(mt!==this._lmt){this._lmt=mt;const d=mt-t;if(Math.abs(d)>.25){this.base=mt;this.perf=now;t=mt}else if(Math.abs(d)>.03){this.base+=d*.35;t+=d*.35}}}
    else{if(!this._hold){this._hold=true;this.base=t}this.perf=now;t=this.base;if(st===2||st===5)YTD.play()}}
   else if(!vid.paused&&!vid.seeking&&vid.readyState>=2){const mt=vid.currentTime;if(Math.abs(mt-t)>.06){this.base=mt;this.perf=now;t=mt}}}
  return t},
 play(){if(this.playing)return;this.playing=true;this.perf=performance.now();this.ended=false;this._hold=false;this._lmt=null;
  if(this.has){if(this.base<0)this.pend=true;else{this.pend=false;
   if(this.kind==='yt'){if(Math.abs(this.mt()-this.base)>.03)this.mseek(this.base);this.mplay()}
   else{vid.playbackRate=this.rate;try{if(Math.abs(vid.currentTime-this.base)>.02)vid.currentTime=this.base}catch(e){}vid.play().catch(()=>BS.toast('재생이 막혔습니다. 화면을 한 번 누르고 다시 시도해 주십시오.'))}}}},
 pause(){if(!this.playing)return;this.base=this.time();this.playing=false;this.pend=false;this._hold=false;if(this.has)this.mpause()},
 seek(t){this.base=t;this.perf=performance.now();this.ended=false;this._hold=false;this._lmt=null;if(this.has){if(t>=0){this.mseek(t);this.pend=false;if(this.playing&&(this.kind==='yt'||vid.paused))this.mplay().catch(()=>{})}else{this.mpause();this.mseek(0);if(this.playing)this.pend=true}}},
 setRate(r){const t=this.time();this.rate=r;this.base=t;this.perf=performance.now();vid.playbackRate=r;if(this.kind==='yt')YTD.rate(r)}
};
vid.addEventListener('ended',()=>{P.ended=true});

/* ---------- song helpers ---------- */
BS.bms=s=>60000/s.bpm;
BS.b2ms=(s,b)=>s.offset+b*60000/s.bpm;
BS.newChar=i=>({name:'캐릭터 '+(i+1),img:{idle:null,combo:null,miss:null},jump:100,size:100,flip:false});
BS.normNotes=a=>(Array.isArray(a)?a:[]).filter(n=>n&&isFinite(n.b)&&n.l>=0&&n.l<4).map(n=>n.e!=null&&n.e>n.b?{b:+n.b,l:n.l|0,e:+n.e}:{b:+n.b,l:n.l|0});
/* song data: title, artist, bpm, offset, length, previewStart, comboTh, missMs, chars, charts{easy,normal,hard:{level,notes}} */
BS.normSong=o=>{const s=Object.assign({title:'새 곡',artist:'',bpm:120,offset:0,length:90,previewStart:0,chars:[],comboTh:10,missMs:700},o||{});
 s.bpm=+s.bpm>0?+s.bpm:120;s.offset=+s.offset||0;s.length=+s.length>0?+s.length:90;s.previewStart=+s.previewStart||0;s.comboTh=+s.comboTh||10;s.missMs=+s.missMs||700;
 const ch=s.charts&&typeof s.charts==='object'?s.charts:{};const lv={easy:1,normal:3,hard:5};
 s.charts={};for(const d of BS.DIFFS){const c=ch[d.k]||{};s.charts[d.k]={level:+c.level||lv[d.k],notes:BS.normNotes(c.notes)}}
 if(Array.isArray(o&&o.notes)&&!s.charts.normal.notes.length){s.charts.normal.notes=BS.normNotes(o.notes);if(o.level)s.charts.normal.level=+o.level}
 delete s.notes;delete s.level;
 s.chars=(Array.isArray(s.chars)&&s.chars.length?s.chars:[BS.newChar(0)]).slice(0,5).map((c,i)=>{const d=BS.newChar(i);return Object.assign(d,c,{img:Object.assign(d.img,c&&c.img||{})})});return s};

/* default character art */
const CC=['#ffd43b','#18d8e0','#ff9fca','#8fb3ff','#ffa94d'],defCache={};
BS.defChar=(i,m)=>{const k=i%5+m;if(defCache[k])return defCache[k];const c=CC[i%5];
 const eyes=m==='miss'?'<path d="M66 88l16 12M82 88l-16 12M118 88l16 12M134 88l-16 12" stroke="#1a2228" stroke-width="6" stroke-linecap="round"/>':m==='combo'?'<path d="M64 98q10-14 20 0M116 98q10-14 20 0" stroke="#1a2228" stroke-width="6" fill="none" stroke-linecap="round"/>':'<ellipse cx="76" cy="94" rx="7" ry="9" fill="#1a2228"/><ellipse cx="124" cy="94" rx="7" ry="9" fill="#1a2228"/><circle cx="78" cy="91" r="2.5" fill="#fff"/><circle cx="126" cy="91" r="2.5" fill="#fff"/>';
 const mouth=m==='miss'?'<path d="M84 132q16-12 32 0" stroke="#1a2228" stroke-width="6" fill="none" stroke-linecap="round"/>':m==='combo'?'<path d="M78 116q22 34 44 0z" fill="#1a2228"/><path d="M88 128q12 8 24 0" fill="#ff8aa0"/>':'<path d="M86 118q14 12 28 0" stroke="#1a2228" stroke-width="6" fill="none" stroke-linecap="round"/>';
 const arms=m==='combo'?`<path d="M34 150Q14 110 22 70M166 150Q186 110 178 70" stroke="${c}" stroke-width="16" fill="none" stroke-linecap="round"/>`:m==='miss'?`<path d="M36 160Q20 196 30 222M164 160Q180 196 170 222" stroke="${c}" stroke-width="16" fill="none" stroke-linecap="round"/>`:`<path d="M36 156Q12 176 22 206M164 156Q188 176 178 206" stroke="${c}" stroke-width="16" fill="none" stroke-linecap="round"/>`;
 const extra=m==='miss'?'<path d="M150 108q6 10 0 16q-6-6 0-16z" fill="#8fd3ff"/>':'<ellipse cx="62" cy="114" rx="11" ry="6" fill="#fff" opacity=".4"/><ellipse cx="138" cy="114" rx="11" ry="6" fill="#fff" opacity=".4"/>';
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 270">${arms}<rect x="70" y="222" width="22" height="40" rx="10" fill="#1a2228"/><rect x="108" y="222" width="22" height="40" rx="10" fill="#1a2228"/><path d="M100 16C48 16 30 60 30 120c0 70 26 112 70 112s70-42 70-112C170 60 152 16 100 16z" fill="${c}"/><path d="M58 40q42-26 84 0" stroke="#fff" stroke-width="8" fill="none" opacity=".45" stroke-linecap="round"/>${eyes}${mouth}${extra}</svg>`;
 return defCache[k]='data:image/svg+xml,'+encodeURIComponent(svg)};
BS.charSrc=(c,i,st)=>c.img[st]||c.img.idle||BS.defChar(i,st);

/* ---------- stage: still at rest, small hop on hits ---------- */
const Stage=BS.Stage={
 html:'<div class="platform"><div class="glow"></div><div class="top"></div><div class="lip"></div><div class="stage"></div></div>',
 build(el,song){el._song=song;el._st=song.chars.map(()=>({h0:-1e9,amp:0,sh:-1e9,fl:-1e9,sd:1}));el.innerHTML='';song.chars.forEach(c=>{const d=document.createElement('div');d.className='ch';d.style.setProperty('--sz',(+c.size||100)/100);const im=document.createElement('img');im.alt='';im.draggable=false;d.appendChild(im);el.appendChild(d)});Stage.size(el)},
 size(el){const s=el._song;if(!s)return;const n=Math.max(1,s.chars.length),w=el.clientWidth||300,h=el.clientHeight||150;el.style.setProperty('--cw',Math.min(w*.9/n,h*.8,280)+'px')},
 // which stage characters a lane belongs to: 1 → all lanes, 2 → DF|JK, 3 → D|FJ|K, 4 → one each, 5+ → spread, centre takes F and J
 owners(n,l){if(n<=0)return[];if(n===1)return[0];if(n===2)return[l<2?0:1];if(n===3)return[l===0?0:l===3?2:1];if(n===4)return[l];
  const m=(n-1)/2,o=[Math.round((l+.5)/4*n-.5)];if(n%2&&(l===1||l===2))o.push(m);return[...new Set(o)]},
 // rapid hits don't restart the hop (that looked like trembling): the first hit hops, the rest are counted,
 // and once the run of hits stops a single bigger hop follows (see tick)
 hop(el,amp=1,lane){const now=performance.now(),st=el._st||[],who=lane==null?null:Stage.owners(st.length,lane);st.forEach((s,i)=>{if(who&&!who.includes(i))return;
  const busy=now-s.h0<(s.amp>2?420:240)||now-(s.last||-1e9)<170;s.last=now;
  if(!busy){s.h0=now+(who?0:i*14)+Math.random()*30;s.amp=amp;s.streak=0;s.qamp=0}else{s.streak=(s.streak||0)+1;s.qamp=Math.max(s.qamp||0,amp)}})},
 shake(el){const now=performance.now();(el._st||[]).forEach((s,i)=>{if(now-s.sh>380){s.sh=now+i*25;s.sd=Math.random()<.5?-1:1}})},
 flip(el,lane){const now=performance.now(),st=el._st||[],who=lane==null?null:Stage.owners(st.length,lane);st.forEach((s,i)=>{if(who&&!who.includes(i))return;const d=who?0:i*45;s.fl=now+d;s.h0=now+d;s.amp=3.2;s.streak=0;s.qamp=0;s.last=now})},
 tick(el,state,beat){const s=el._song;if(!s)return;const now=performance.now(),kids=el.children;
  // groove: a small dip on every beat of the song's BPM
  const gb=beat!=null&&beat>=0?Math.exp(-(beat%1)*7):0;
  for(let i=0;i<kids.length;i++){const c=s.chars[i],st=el._st[i];if(!c||!st)continue;const im=kids[i].firstChild;const src=BS.charSrc(c,c.__i??i,state);if(im._s!==src){im.src=src;im._s=src}
   if(st.streak&&now-st.last>170&&now-st.h0>(st.amp>2?420:240)){st.h0=now;st.amp=Math.min(2.4,st.qamp*(1.35+.12*Math.min(st.streak,6)));st.streak=0;st.qamp=0}
   const h=kids[i].clientHeight||100;let ty=0,tx=0,sx=1,sy=1;const dt=now-st.h0,D=st.amp>2?420:240;
   if(dt>=0&&dt<D){const p=dt/D,j=(c.jump??100)/100;ty=-Math.sin(Math.PI*p)*h*.045*st.amp*j;if(p>.8){const q=Math.sin(Math.PI*(p-.8)/.2)*j;sy=1-.03*q*st.amp;sx=1+.02*q*st.amp}}
   if(gb){ty+=h*.022*gb;sy*=1-.035*gb;sx*=1+.025*gb}
   let rot=0;const ds=now-st.sh,DS=560;if(ds>=0&&ds<DS){const p=ds/DS,k=Math.sin(Math.PI*Math.min(1,p*1.6))*(1-p);rot=st.sd*16*k;ty+=h*.03*k;sy*=1-.05*k;tx=st.sd*h*.02*k}
   const df=now-st.fl,DF=480;if(df>=0&&df<DF){const p=df/DF,e=p<.5?2*p*p:1-Math.pow(-2*p+2,2)/2;sx*=Math.cos(e*Math.PI*2)}
   if(c.flip)sx*=-1;im.style.transform=`translate(${tx.toFixed(1)}px,${ty.toFixed(1)}px) rotate(${rot.toFixed(2)}deg) scale(${sx.toFixed(3)},${sy.toFixed(3)})`}}
};

