function clearCfx(){}
function showCombo(){const c=$('#g-combo');if(G.combo<2){c.classList.add('off');return}
 c.classList.remove('off');c.querySelector('.cn').textContent=G.combo;c.classList.remove('pop');void c.offsetWidth;c.classList.add('pop')}
/* full combo call-out: as soon as the last note is judged without a miss/bad */
function checkFC(){if(G.fcShown||G.failed||G.judged<G.total||!G.total)return;const c=G.cnt;if(c.MISS+c.BAD>0)return;G.fcShown=true;
 const ap=c.PERFECT===G.total,el=$('#g-fc');el.querySelector('b').textContent=ap?'ALL PERFECT':'FULL COMBO';el.classList.toggle('ap',ap);el.classList.remove('on');void el.offsetWidth;el.classList.add('on');$('#g-combo').classList.add('off');
 AU.play('fan',.7);const g=G.geo;if(g){for(let l=0;l<4;l++)spark(l,true)}}
function holdTick(l){G.combo++;if(G.combo>G.maxCombo)G.maxCombo=G.combo;G.beam[l]=1;showCombo();Stage.hop(stEl,.4,l);
 spark(l,false,true)}
function updHud(){const r=G.total?G.pts/G.total:0;$('#g-score').textContent=Math.round(1e6*r).toLocaleString('en-US');$('#g-gauge').style.width=r*100+'%'}

function press(l){if(!G.running||G.paused||G.finished)return;G.held[l]=true;G.beam[l]=1;let hit=false;
 const t=G.t,a=G.lanes[l];for(let i=G.ptr[l];i<a.length;i++){const n=a[i];if(n.done)continue;const dt=t-n.t;if(dt<-JW.BAD)break;
  const g=grade(Math.abs(dt));n.done=true;hit=g!=='BAD';if(SET.hitSound&&hit)AU.play('hit',1);judge(g,dt,l);if(g!=='BAD')spark(l);
  if(n.e!=null){if(g==='BAD'){n.tail=true;n.broken=true;judge('MISS',0)}else G.hold[l]=n}break}
 if(!hit&&SET.hitSound)AU.play('tap',AU.has('tap')?1:.5)}
function release(l){G.held[l]=false;const h=G.hold[l];if(!h||!G.running||G.paused||G.finished)return;G.hold[l]=null;h.tail=true;const dt=G.t-h.e;
 if(dt>=-JW.GOOD){judge(grade(Math.abs(dt)),dt,l);spark(l,true);Stage.flip(stEl,l)}else{h.broken=true;judge('MISS',0)}}
function spark(l,big,tick){const g=G.geo;if(!g)return;const x=xOf(g,l+.5,1),y=g.jy,c=tick?NL:BS.LC[l],R=g.hb/9*(tick?.8:1);
 G.parts.push({flash:1,x,y,r:R*1.6,life:1,c},{ring:1,x,y,r:R*.55,life:1,c,sp:2.4,w:5},{ring:1,x,y,r:R*.35,life:1,c:'#ffffff',sp:3.4,w:3},{beam:1,l,life:1,c});
 const n=big?26:tick?12:20;for(let i=0;i<n;i++){const a=-Math.PI*(.05+.9*Math.random()),v=3+Math.random()*7;G.parts.push({x,y,vx:Math.cos(a)*v*1.3,vy:Math.sin(a)*v,life:1,c:i%3===0?'#ffffff':i%3===1?c:'#4ff0d0',kind:i%4===0?'star':i%2?'sq':'dot',sz:2+Math.random()*3.5})}}

function quad(x,pts){x.beginPath();x.moveTo(pts[0],pts[1]);for(let i=2;i<pts.length;i+=2)x.lineTo(pts[i],pts[i+1]);x.closePath()}
function render(t){const[W,H]=fit(gc,gx);const g=geom(W,H);G.geo=g;const s=G.song,vis=6500/SET.speed,{jy,top}=g;
 gx.clearRect(0,0,W,H);
 const sT=sOf(g,1);
 // highway body
 quad(gx,[xOf(g,0,sT),top,xOf(g,4,sT),top,xOf(g,4,1),jy,xOf(g,0,1),jy]);
 const lg=gx.createLinearGradient(0,top,0,jy);lg.addColorStop(0,`rgba(8,18,24,${SET.laneOp*.25})`);lg.addColorStop(1,`rgba(8,18,24,${SET.laneOp})`);gx.fillStyle=lg;gx.fill();
 // beat lines
 const bm=BS.bms(s);for(let b=Math.ceil((t-s.offset)/bm),k=0;k<200;b++,k++){const u=(s.offset+b*bm-t)/vis;if(u>1)break;if(u<0)continue;const ss=sOf(g,u),y=yOf(g,ss);gx.fillStyle=b%4===0?`rgba(255,255,255,${.22*ss})`:`rgba(255,255,255,${.07*ss})`;gx.fillRect(xOf(g,0,ss),y,g.hb*ss,b%4===0?2:1)}
 // beams
 for(let l=0;l<4;l++){if(G.beam[l]>.02){const u2=.55,s2=sOf(g,u2),y2=yOf(g,s2);quad(gx,[xOf(g,l,s2),y2,xOf(g,l+1,s2),y2,xOf(g,l+1,1),jy,xOf(g,l,1),jy]);const gr=gx.createLinearGradient(0,jy,0,y2);gr.addColorStop(0,hexA(BS.LC[l],.45*G.beam[l]));gr.addColorStop(1,hexA(BS.LC[l],0));gx.fillStyle=gr;gx.fill()}}
 // lane separators + rails
 gx.lineWidth=1;for(let l=1;l<4;l++){gx.strokeStyle='rgba(255,255,255,.12)';gx.beginPath();gx.moveTo(xOf(g,l,sT),top);gx.lineTo(xOf(g,l,1),jy);gx.stroke()}
 gx.shadowColor=RAIL;gx.shadowBlur=12;gx.strokeStyle=hexA(RAIL,.95);gx.lineWidth=2.5;for(const e of [0,4]){gx.beginPath();gx.moveTo(xOf(g,e,sT),top);gx.lineTo(xOf(g,e,1),jy);gx.stroke()}gx.shadowBlur=0;
 // judge line + receptors
 gx.shadowColor='#fff';gx.shadowBlur=16;gx.fillStyle='rgba(255,255,255,.95)';gx.fillRect(xOf(g,0,1)-6,jy-2,g.hb+12,4);gx.shadowBlur=0;
 for(let l=0;l<4;l++){const on=G.held[l],x0=xOf(g,l,1)+4,w=g.hb/4-8;rr(gx,x0,jy-8,w,16,8);gx.fillStyle=on?hexA(BS.LC[l],.95):'rgba(255,255,255,.14)';gx.fill();gx.strokeStyle=hexA(BS.LC[l],on?1:.6);gx.lineWidth=1.5;gx.stroke();
  if(!COARSE&&!g.mob){gx.fillStyle=on?'#fff':'rgba(255,255,255,.55)';gx.font=`italic 800 ${Math.min(17,w*.16)}px Rubik,sans-serif`;gx.textAlign='center';gx.textBaseline='middle';gx.fillText(BS.keyName(SET.keys[l]),x0+w/2,jy-26)}}
 // notes
 for(let l=0;l<4;l++){const a=G.lanes[l];let r=G.rs[l];while(r<a.length){const n=a[r];if(n.done&&(n.e==null||n.tail)&&(n.e??n.t)<t-60)r++;else break}G.rs[l]=r;
  for(let i=r;i<a.length;i++){const n=a[i],u=(n.t-t)/vis;if(u>1.02)break;
   if(n.e!=null){if(n.tail&&!n.broken)continue;const holding=G.hold[l]===n;
    // a missed (grey) long note is cut off at the judge line instead of sliding below it
    const lim=n.broken?0:-.05,uh=holding?0:Math.max(u,lim),ut=Math.min((n.e-t)/vis,1);if(ut<lim)continue;
    const sh=sOf(g,uh),st=sOf(g,Math.max(ut,uh)),c=n.broken?'#7b8a92':NL;
    quad(gx,[xOf(g,l+.16,st),yOf(g,st),xOf(g,l+.84,st),yOf(g,st),xOf(g,l+.84,sh),yOf(g,sh),xOf(g,l+.16,sh),yOf(g,sh)]);
    const gr=gx.createLinearGradient(0,yOf(g,st),0,yOf(g,sh));gr.addColorStop(0,hexA(lite(c,.3),.45));gr.addColorStop(1,hexA(lite(c,.3),holding?.95:.75));gx.fillStyle=gr;gx.fill();
    if(ut<=1)drawNote(g,l,st,c,.6);if(!(n.done&&!holding&&!n.broken)&&uh<=1&&!(n.broken&&u<0))drawNote(g,l,sh,c,1)}
   else{if(n.done||u<-.05)continue;drawNote(g,l,sOf(g,u),NT,1)}}}
 // held long notes: pulsing glow on the judge line + a steady stream of sparks
 for(let l=0;l<4;l++){if(!G.hold[l]||!G.held[l]||G.paused)continue;const x=xOf(g,l+.5,1),c=NL,R=g.hb/9,ph=performance.now()/1000,pr=R*(1.05+.2*Math.sin(ph*16));
  const gr=gx.createRadialGradient(x,jy,0,x,jy,pr);gr.addColorStop(0,'rgba(255,255,255,.9)');gr.addColorStop(.35,hexA(c,.6));gr.addColorStop(1,hexA(c,0));gx.fillStyle=gr;gx.beginPath();gx.ellipse(x,jy,pr,pr*.5,0,0,7);gx.fill();
  for(let k=0;k<2;k++){const a=-Math.PI*(.2+.6*Math.random()),v=2+Math.random()*4.5;G.parts.push({x:x+(Math.random()-.5)*g.hb/7,y:jy,vx:Math.cos(a)*v,vy:Math.sin(a)*v*1.5,life:.75,c:Math.random()<.4?'#ffffff':c,kind:Math.random()<.3?'star':'dot',sz:1.5+Math.random()*2.5})}
  G.beam[l]=Math.max(G.beam[l],.7)}
 // particles
 for(let i=G.parts.length-1;i>=0;i--){const p=G.parts[i];p.life-=.04;if(p.life<=0){G.parts.splice(i,1);continue}gx.globalAlpha=p.life;
  if(p.beam){const s2=sOf(g,.45),y2=yOf(g,s2);quad(gx,[xOf(g,p.l+.1,s2),y2,xOf(g,p.l+.9,s2),y2,xOf(g,p.l+1,1),jy,xOf(g,p.l,1),jy]);const gr=gx.createLinearGradient(0,jy,0,y2);gr.addColorStop(0,hexA('#ffffff',.85*p.life));gr.addColorStop(1,'rgba(255,255,255,0)');gx.fillStyle=gr;gx.fill()}
  else if(p.flash){const k=1-p.life,rr2=p.r*(.6+k*.8),gr=gx.createRadialGradient(p.x,p.y,0,p.x,p.y,rr2);gr.addColorStop(0,'rgba(255,255,255,'+(.9*p.life)+')');gr.addColorStop(.35,hexA(p.c,.6*p.life));gr.addColorStop(1,hexA(p.c,0));gx.fillStyle=gr;gx.beginPath();gx.ellipse(p.x,p.y,rr2,rr2*.55,0,0,7);gx.fill();p.life-=.03}
  else if(p.ring){const sp=p.sp||1.8;gx.strokeStyle=p.c;gx.lineWidth=(p.w||3)*p.life;gx.shadowColor=p.c;gx.shadowBlur=10;gx.beginPath();gx.ellipse(p.x,p.y,p.r*(1+(1-p.life)*sp),p.r*.45*(1+(1-p.life)*sp),0,0,7);gx.stroke();gx.shadowBlur=0}
  else if(p.kind){p.x+=p.vx;p.y+=p.vy;p.vy+=.22;p.vx*=.97;gx.fillStyle=p.c;const z=p.sz||3;if(p.kind==='star'){gx.save();gx.translate(p.x,p.y);gx.rotate(p.life*8);gx.beginPath();for(let k=0;k<10;k++){const rad=k%2?z*.9:z*2.4,a=k*Math.PI/5;gx.lineTo(Math.cos(a)*rad,Math.sin(a)*rad)}gx.closePath();gx.shadowColor=p.c;gx.shadowBlur=8;gx.fill();gx.restore();gx.shadowBlur=0}else if(p.kind==='sq'){gx.save();gx.translate(p.x,p.y);gx.rotate(p.life*6);gx.fillRect(-z,-z,z*2,z*2);gx.restore()}else{gx.beginPath();gx.arc(p.x,p.y,z*.8,0,7);gx.fill()}}
  else{p.x+=p.vx;p.y+=p.vy;p.vy+=.18;gx.fillStyle=p.c;if(p.sq){gx.save();gx.translate(p.x,p.y);gx.rotate(p.life*6);gx.fillRect(-3,-3,6,6);gx.restore()}else{gx.beginPath();gx.arc(p.x,p.y,2.2,0,7);gx.fill()}}}
 gx.globalAlpha=1;
 const jd=$('#g-judge'),cb=$('#g-combo');jd.style.left=cb.style.left=g.cx+'px';jd.style.top=(jy-(jy-top)*.26)+'px';cb.style.top=(jy-(jy-top)*.56)+'px'}
function drawNote(g,l,s,c,a,X=gx){const y=yOf(g,s),x0=xOf(g,l+.05,s),w=g.hb/4*.9*s,h=Math.max(5,17*s);X.globalAlpha=Math.min(1,a*(s<.35?(s-.22)/.13:1));if(X.globalAlpha<=0){X.globalAlpha=1;return}
 rr(X,x0,y-h/2,w,h,h/2);const gr=X.createLinearGradient(0,y-h/2,0,y+h/2);const cl=lite(c,.38);gr.addColorStop(0,'#ffffff');gr.addColorStop(.5,cl);gr.addColorStop(1,lite(c,.18));X.fillStyle=gr;X.shadowColor=c;X.shadowBlur=Math.max(4,12*s);X.fill();X.shadowBlur=0;
 X.lineWidth=Math.max(1,2*s);X.strokeStyle='rgba(255,255,255,.9)';X.stroke();X.fillStyle='rgba(255,255,255,.85)';X.fillRect(x0+w*.3,y-Math.max(1,1.5*s),w*.4,Math.max(2,3*s));X.globalAlpha=1}
/* settings live preview: auto-played notes at the current speed / sound */
function settingsPreview(cv){const X=cv.getContext('2d'),t0=performance.now(),half=60000/150/2,pat=[0,2,1,3,1,2,0,3,0,1,2,3,3,2,1,0],fl=[0,0,0,0],parts=[];let last=-1,cnt=0;
 const step=()=>{if(!cv.isConnected)return;requestAnimationFrame(step);const[W,H]=fit(cv,X);if(!W||!H)return;const jy=H*.86,top=14,K=3.4,g={cx:W/2,hb:W*.92,jy,top,K,vy:(top*(1+K)-jy)/K},vis=6500/SET.speed,t=performance.now()-t0,sT=sOf(g,1);
  X.clearRect(0,0,W,H);X.fillStyle='#0a1115';X.fillRect(0,0,W,H);quad(X,[xOf(g,0,sT),top,xOf(g,4,sT),top,xOf(g,4,1),jy,xOf(g,0,1),jy]);const lg=X.createLinearGradient(0,top,0,jy);lg.addColorStop(0,`rgba(30,50,60,${SET.laneOp*.3})`);lg.addColorStop(1,`rgba(30,50,60,${SET.laneOp})`);X.fillStyle=lg;X.fill();
  X.lineWidth=1;X.strokeStyle='rgba(255,255,255,.12)';for(let l=1;l<4;l++){X.beginPath();X.moveTo(xOf(g,l,sT),top);X.lineTo(xOf(g,l,1),jy);X.stroke()}X.strokeStyle=hexA(RAIL,.95);X.lineWidth=2;for(const e of [0,4]){X.beginPath();X.moveTo(xOf(g,e,sT),top);X.lineTo(xOf(g,e,1),jy);X.stroke()}
  for(let l=0;l<4;l++){if(fl[l]>.02){const s2=sOf(g,.5),y2=yOf(g,s2);quad(X,[xOf(g,l,s2),y2,xOf(g,l+1,s2),y2,xOf(g,l+1,1),jy,xOf(g,l,1),jy]);const gr=X.createLinearGradient(0,jy,0,y2);gr.addColorStop(0,hexA(BS.LC[l],.5*fl[l]));gr.addColorStop(1,hexA(BS.LC[l],0));X.fillStyle=gr;X.fill()}fl[l]*=.86;rr(X,xOf(g,l,1)+3,jy-6,g.hb/4-6,12,6);X.fillStyle=hexA(BS.LC[l],.25+.6*fl[l]);X.fill()}
  X.fillStyle='rgba(255,255,255,.95)';X.fillRect(xOf(g,0,1)-4,jy-1.5,g.hb+8,3);
  const k0=Math.max(0,Math.floor((t-900)/half));for(let k=k0;k<k0+400;k++){const nt=900+k*half,u=(nt-t)/vis;if(u>1.02)break;const l=pat[k%pat.length];if(u<=0){if(k>last){last=k;cnt++;fl[l]=1;parts.push({x:xOf(g,l+.5,1),y:jy,r:g.hb/14,life:1,c:BS.LC[l]});if(SET.hitSound)AU.play('hit',1)}continue}drawNote(g,l,sOf(g,u),NT,1,X)}
  for(let i=parts.length-1;i>=0;i--){const p=parts[i];p.life-=.05;if(p.life<=0){parts.splice(i,1);continue}X.globalAlpha=p.life;X.strokeStyle=p.c;X.lineWidth=3*p.life;X.beginPath();X.ellipse(p.x,p.y,p.r*(1+(1-p.life)*1.6),p.r*.45*(1+(1-p.life)*1.6),0,0,7);X.stroke()}X.globalAlpha=1;
  X.font='italic 800 13px Rubik,sans-serif';X.textAlign='center';X.fillStyle=cnt?'#fff':'transparent';X.fillText(cnt+' COMBO',W/2,jy*.45);X.fillStyle='#93a4ae';X.font='600 12px Noto Sans KR,sans-serif';X.fillText('노트 속도 '+SET.speed,W/2,H-12)};step()}

/* touch / pointer: whole screen maps by x to lanes */
const tp=new Map();
function laneAt(cx){const g=G.geo;if(!g)return-1;const r=gc.getBoundingClientRect();return clamp(Math.floor(((cx-r.left)-(g.cx-g.hb/2))/(g.hb/4)),0,3)}
gc.addEventListener('pointerdown',e=>{e.preventDefault();AU.init();const l=laneAt(e.clientX);if(l<0)return;try{gc.setPointerCapture(e.pointerId)}catch(_){}tp.set(e.pointerId,l);press(l)});
gc.addEventListener('pointermove',e=>{if(!tp.has(e.pointerId))return;const o=tp.get(e.pointerId),l=laneAt(e.clientX);if(l>=0&&l!==o){tp.set(e.pointerId,l);if(![...tp.values()].includes(o))release(o);press(l)}});
const tUp=e=>{if(!tp.has(e.pointerId))return;const l=tp.get(e.pointerId);tp.delete(e.pointerId);if(![...tp.values()].includes(l))release(l)};
gc.addEventListener('pointerup',tUp);gc.addEventListener('pointercancel',tUp);sec.addEventListener('contextmenu',e=>e.preventDefault());

function pause(){if(!G.running||G.finished||G.paused)return;G.paused=true;P.pause();$('#g-pm').classList.add('on')}
function resume(){$('#g-pm').classList.remove('on');G.paused=false;for(let l=0;l<4;l++)if(G.hold[l]&&!G.held[l])release(l);P.play()}
function exit(reason){G.running=false;G.active=false;cancelAnimationFrame(G.raf);cancelAnimationFrame(G.rraf);clearTimeout(G.ot);stopConf();hideBubble();P.pause();BS.swoosh();sec.classList.remove('on','res-on','over','ending','low','enter');$('#g-pm').classList.remove('on');tp.clear();if(G.opt.onExit)G.opt.onExit(reason)}
$('#g-pause').onclick=pause;$('#p-resume').onclick=resume;$('#p-restart').onclick=()=>BS.play(G.song,G.opt);$('#p-quit').onclick=()=>exit('quit');
$('#g-skip').onclick=()=>finish();
