  const p=clamp((el-500)/1300,0,1),e=1-Math.pow(1-p,3);
  if(el>500&&!G.cs0){G.cs0=1;G.ctk=0;if(AU.has('score'))AU.play('score',1)}
  if(G.cs0&&!AU.has('score')&&sc>0){if(p<1&&now-G.ctk>65){G.ctk=now;AU.play('tick',.35,1+e*1.2)}if(p>=1&&G.cs0===1){G.cs0=2;AU.play('ding',.7)}}$('#r-score').textContent=Math.round(sc*e).toLocaleString('en-US');$('#r-gauge').style.width=(sc/1e4*e)+'%';
