/* result speaker stands just right of the result card (wide screens) */
function placeRChar(){const im=$('#r-char'),c=sec.querySelector('.rcard');if(!c||innerWidth<=900){im.style.left='';im.style.right='';return}const r=c.getBoundingClientRect(),R=sec.getBoundingClientRect();im.style.left=Math.round(r.right-R.left+8)+'px';im.style.right='auto'}
/* speech bubble */
function showBubble(text){if(!sec.classList.contains('res-on'))return;G.bub={};$('#r-line').textContent=text;
 placeBubble();AU.play('pop',.5);const b=$('#r-bubble');b.classList.remove('on');void b.offsetWidth;b.classList.add('on')}
function placeBubble(){const b=$('#r-bubble'),im=$('#r-char'),r=im.getBoundingClientRect(),R=sec.getBoundingClientRect();if(!r.width)return;
 const nw=im.naturalWidth||3,nh=im.naturalHeight||4,dw=Math.min(r.width,r.height*nw/nh),dh=dw*nh/nw,leftAl=/^0(%|px)?\s/.test(getComputedStyle(im).objectPosition),left=r.left-R.left+(leftAl?0:(r.width-dw)/2),top=r.bottom-dh-R.top;
 b.style.left='0px';b.style.top='0px';const bw=b.offsetWidth,bh=b.offsetHeight,mob=R.width<=900;let x,y;
 if(mob){x=clamp(left-bw+dw*.2,8,R.width-bw-8);y=clamp(top+dh*.35-bh,6,R.height-bh-8)}else{x=clamp(left+dw/2-bw*.7,8,R.width-bw-8);y=clamp(top-bh-12,6,R.height-bh-8)}
 b.style.left=x+'px';b.style.top=y+'px';b.style.setProperty('--tx',clamp(left+dw*(mob?.25:.5)-x-9,14,bw-32)+'px');b.style.setProperty('--ox',(mob?100:70)+'%')}
function hideBubble(){clearTimeout(G.bt);clearTimeout(G.bt2);G.bub=null;$('#r-bubble').classList.remove('on');$('#r-char').classList.remove('on')}

/* confetti */
const cf=$('#r-conf'),cx=cf.getContext('2d');let conf=[],cfRaf=0;
function startConf(n,rank){stopConf();if(!n||matchMedia('(prefers-reduced-motion:reduce)').matches)return;const[W,H]=fit(cf,cx);const cols=rank==='S'?[YE,'#ffffff',CY,'#ffe98a','#ff9fca']:[CY,YE,'#ff9fca','#8fb3ff','#ffffff'];
 for(let i=0;i<n;i++){const burst=i<n*.45;conf.push({x:burst?W/2+(Math.random()-.5)*60:Math.random()*W,y:burst?H*.32:-20-Math.random()*H*.6,vx:burst?(Math.random()-.5)*16:(Math.random()-.5)*1.5,vy:burst?-Math.random()*12-2:Math.random()*2+1,r:Math.random()*6.28,vr:(Math.random()-.5)*.3,w:6+Math.random()*6,h:4+Math.random()*5,c:cols[i%cols.length],star:i%5===0})}
 const step=()=>{const[W2,H2]=fit(cf,cx);cx.clearRect(0,0,W2,H2);let alive=0;for(const p of conf){if(p.y>H2+30)continue;alive++;p.vy+=.18;p.vx*=.985;p.vy=Math.min(p.vy,4.5);p.x+=p.vx+Math.sin(p.r*2)*.6;p.y+=p.vy;p.r+=p.vr;cx.save();cx.translate(p.x,p.y);cx.rotate(p.r);cx.fillStyle=p.c;
   if(p.star){cx.beginPath();for(let k=0;k<10;k++){const rad=k%2?3:7,a=k*Math.PI/5;cx.lineTo(Math.cos(a)*rad,Math.sin(a)*rad)}cx.closePath();cx.fill()}else{cx.scale(1,Math.cos(p.r*1.7));cx.fillRect(-p.w/2,-p.h/2,p.w,p.h)}cx.restore()}
  if(alive)cfRaf=requestAnimationFrame(step);else cx.clearRect(0,0,W2,H2)};cfRaf=requestAnimationFrame(step)}
function stopConf(){cancelAnimationFrame(cfRaf);conf=[];try{const[W,H]=fit(cf,cx);cx.clearRect(0,0,W,H)}catch(e){}}

/* generic confetti burst on any canvas */
BS.burst=(cv,n=160,ox=.5,oy=.4)=>{const X=cv.getContext('2d');const[W,H]=fit(cv,X);const cols=[YE,CY,'#ffffff','#ff9fca','#8fb3ff'];const ps=[];for(let i=0;i<n;i++){const a=Math.random()*Math.PI*2,v=4+Math.random()*12;ps.push({x:W*ox,y:H*oy,vx:Math.cos(a)*v,vy:Math.sin(a)*v-5,r:Math.random()*6,vr:(Math.random()-.5)*.3,w:6+Math.random()*6,h:4+Math.random()*5,c:cols[i%5],star:i%4===0})}
 cancelAnimationFrame(cv._raf);const step=()=>{const[W2,H2]=fit(cv,X);X.clearRect(0,0,W2,H2);let alive=0;for(const p of ps){if(p.y>H2+30)continue;alive++;p.vy+=.25;p.vx*=.97;p.x+=p.vx;p.y+=p.vy;p.r+=p.vr;X.save();X.translate(p.x,p.y);X.rotate(p.r);X.fillStyle=p.c;if(p.star){X.beginPath();for(let k=0;k<10;k++){const rad=k%2?3:8,a=k*Math.PI/5;X.lineTo(Math.cos(a)*rad,Math.sin(a)*rad)}X.closePath();X.fill()}else{X.scale(1,Math.cos(p.r*1.7));X.fillRect(-p.w/2,-p.h/2,p.w,p.h)}X.restore()}if(alive)cv._raf=requestAnimationFrame(step);else X.clearRect(0,0,W2,H2)};cv._raf=requestAnimationFrame(step)};

/* ---------- touch effect: star (or the developer's image) + sparkles wherever the screen is touched ---------- */
BS.touchImg=null;BS.setTouchImage=src=>{if(!src){BS.touchImg=null;return}const im=new Image();im.onload=()=>{BS.touchImg=im};im.src=src};
{const fx=document.createElement('canvas');fx.id='bs-touchfx';fx.style.cssText='position:fixed;inset:0;width:100%;height:100%;z-index:500;pointer-events:none';document.body.appendChild(fx);
 const X=fx.getContext('2d'),P=[];let raf=0,last=0;
 const star=(x,y,r,rot,inner=.45,pts=5)=>{X.beginPath();for(let k=0;k<pts*2;k++){const rad=k%2?r*inner:r,a=rot+k*Math.PI/pts-Math.PI/2;X.lineTo(x+Math.cos(a)*rad,y+Math.sin(a)*rad)}X.closePath()};
 const img=(x,y,r,rot)=>{const im=BS.touchImg,s=r*2.2,k=im.naturalWidth/im.naturalHeight||1,w=k>=1?s:s*k,h=k>=1?s/k:s;X.save();X.translate(x,y);X.rotate(rot);X.drawImage(im,-w/2,-h/2,w,h);X.restore()};
 const step=ts=>{const dt=Math.min(.05,last?(ts-last)/1000:1/60);last=ts;const d=Math.min(2,devicePixelRatio||1),w=innerWidth,h=innerHeight;if(fx.width!==Math.round(w*d)||fx.height!==Math.round(h*d)){fx.width=Math.round(w*d);fx.height=Math.round(h*d)}X.setTransform(d,0,0,d,0,0);X.clearRect(0,0,w,h);const useImg=BS.touchImg&&BS.touchImg.complete;
  for(let i=P.length-1;i>=0;i--){const p=P[i];p.t+=dt;const k=p.t/p.life;if(k>=1){P.splice(i,1);continue}X.globalAlpha=1-k*k;const f=dt*60;
   if(p.type==='ring'){X.strokeStyle=p.c;X.lineWidth=2.5*(1-k);X.beginPath();X.arc(p.x,p.y,6+46*Math.sqrt(k),0,7);X.stroke()}
   else if(p.type==='big'){const sc=k<.2?k/.2*1.15:1.15-(k-.2)*.35,yy=p.y-k*16,rot=p.rot+k*1.1;if(useImg)img(p.x,yy,p.r*sc,rot*.3);else{X.fillStyle=p.c;X.shadowColor=p.c;X.shadowBlur=14;star(p.x,yy,p.r*sc,rot);X.fill();X.shadowBlur=0;X.fillStyle='#fff';star(p.x,yy,p.r*sc*.45,rot);X.fill()}}
   else{p.x+=p.vx*f;p.y+=p.vy*f;const dm=Math.pow(.955,f);p.vx*=dm;p.vy=p.vy*dm+.035*f;const r=p.r*(1-k*.5);if(useImg)img(p.x,p.y,r*.9,p.rot+k*2);else{X.fillStyle=p.c;if(p.type==='tw')star(p.x,p.y,r,p.rot,.22,4);else star(p.x,p.y,r,p.rot+k*3,.45,5);X.fill()}}}
  X.globalAlpha=1;if(P.length)raf=requestAnimationFrame(step);else{raf=0;last=0;X.clearRect(0,0,w,h)}};
 BS.touchFx=(x,y)=>{const cols=['#4ff0d0','#18d8e0','#ffffff','#b8fff0'];P.push({type:'ring',x,y,t:0,life:.5,c:'rgba(180,255,240,.9)'},{type:'big',x,y,t:0,life:.65,r:16,rot:Math.random(),c:'#4ff0d0'});
  for(let i=0;i<9;i++){const a=Math.random()*Math.PI*2,v=1.4+Math.random()*2.6;P.push({type:i%3?'tw':'st',x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,t:0,life:.55+Math.random()*.3,r:3+Math.random()*4,rot:Math.random()*3,c:cols[i%4]})}
  if(!raf)raf=requestAnimationFrame(step)};
 BS.clickSound=true;addEventListener('pointerdown',e=>{if(BS.G&&BS.G.running&&!BS.G.finished&&!BS.G.paused)return;BS.touchFx(e.clientX,e.clientY);if(BS.clickSound){AU.init();AU.play('click',.5)}},{capture:true,passive:true})}

/* ---------- tiny zip (store) writer & reader ---------- */
const CRC=(()=>{const t=new Uint32Array(256);for(let n=0;n<256;n++){let c=n;for(let k=0;k<8;k++)c=c&1?0xEDB88320^(c>>>1):c>>>1;t[n]=c>>>0}return t})();
